    ELSIF REQCD = '01' OR REQCD = '02' OR REQCD = '08' THEN    
       SELECT COUNT(*)
         INTO VCNT
         FROM CMC0110 A
        WHERE A.CC_SRID=ISRID
          AND A.CC_EDITOR=USERID
          AND NVL(A.CC_STATUS,'0') IN ('2','A','C','4','5')
          and cc_srid not in (select cr_itsmid from cmr1000 where cr_status ='0' and cr_qrycd in ('04','03') and cr_srid=cc_srid);
        IF VCNT = 0 THEN
           RETCD := 'NO_010208';
        ELSIF REQCD <> '01' AND REQCD <> '02' THEN
           STATUS := '2';
           RETCD := CHECKINYN(USERID,ISRID,REQCD,USERID,STATUS);
        ELSE
           RETCD := 'OK';
        END IF;
    ELSIF REQCD = '07' OR REQCD = '11' OR REQCD = '03' THEN
       SELECT COUNT(*)
         INTO VCNT
         FROM CMC0110 A
        WHERE A.CC_SRID=ISRID
          AND A.CC_EDITOR=USERID
          AND NVL(A.CC_STATUS,'0') IN ('2','A','C','4','5','9')
          and cc_srid not in (select cr_itsmid from cmr1000 where cr_status ='0' and cr_qrycd in ('04','03') and cr_srid=cc_srid);
        IF VCNT = 0 THEN
           RETCD := 'NO0703';
        ELSIF REQCD <> '01' AND REQCD <> '02' THEN
