    ELSIF REQCD = '04' THEN     --운영적용요청
        --CC_STATUS 2:개발진행중  5:운영적용요청  B:개발검수완료  C:운영적용반려
        SELECT COUNT(*)
         INTO VCNT
         FROM CMC0100 A
        WHERE A.CC_SRID=ISRID
          AND A.CC_OWNER=USERID
          AND NVL(A.CC_STATUS,'0') IN ('2','A','C','4','9');
        IF VCNT = 0 THEN
           RETCD := 'NO04';
        ELSE
           SELECT CC_STATUS
             INTO STATUS
             FROM CMC0100
            WHERE CC_SRID=ISRID
              AND CC_OWNER=USERID;
           IF STATUS <> '2' AND STATUS <> '5' THEN
              RETCD := CHECKINYN(USERID,ISRID,'04',USERID,STATUS);
              IF RETCD = 'OK' THEN
                 RETCD := 'OK';
              ELSE
                 RETCD := 'NO04';
              END IF;
           ELSE
                --긴급SR 여부 체크 Y:긴급 N:일반
                SELECT COUNT(*)
                  INTO VCNT
                  FROM CMC0100
                 WHERE CC_SRID=ISRID
                   AND CC_CHGTYPE = '01';
                IF VCNT > 0 THEN
                    --긴급프로세스 시작
                    RETCD := CHECKINYN(USERID,ISRID,'04',USERID,STATUS);
                    IF RETCD = 'OK' THEN
                        RETCD := 'OK';
                    END IF;
                    --긴급프로세스 끝
                ELSE
                    --20140728 neo. 개발검수 완료 여부 체크 추가 시작
                    --20140728 neo. 상태2 이면 개발검수가 있는지, 있다면 검수가 완료 됐는지 체크
                    --20140728 neo. 개발검수 대상 시스템 여부 체크
                    SELECT COUNT(*)
                      INTO VCNT
                      FROM CMM0030 B,CMR0020 A
                     WHERE A.CR_ISRID=ISRID
                       AND NVL(A.CR_CKOUTUSER,CR_EDITOR)=USERID
                       AND A.CR_SYSCD=B.CM_SYSCD
                       AND A.CR_STATUS not in ('0','7')
                       AND SUBSTR(B.CM_SYSINFO,12,1)='1';
                    IF VCNT > 0 THEN
                        --20140728 neo. 개발검수 있으면 검수완료 상태[B] 이여야함.
                        RETCD := 'NO1';
                    ELSE
                        RETCD := CHECKINYN(USERID,ISRID,'04',USERID,STATUS);
                        IF RETCD = 'OK' THEN
                            RETCD := 'OK';
                        END IF;
                    END IF;
                    --변경후 끝
                    --20140728 neo. 개발검수 완료 여부 체크 추가 끝
                END IF;
            END IF;
        END IF;

    ELSIF REQCD = '63' THEN    --모니터링
       SELECT COUNT(*)
         INTO VCNT
         FROM CMC0110
        WHERE CC_SRID=ISRID
          AND CC_USERID=USERID
          AND CC_STATUS <> '3';
       IF VCNT = 0 THEN
          RETCD := 'NO6300';
       ELSE
          RETCD := 'OK';
       END IF;

       IF RETCD = 'OK'  AND QRYGBN = '01' THEN
          SELECT CC_STATUS
            INTO STATUS
            FROM CMC0110
           WHERE CC_SRID=ISRID
             AND CC_USERID=USERID;
          IF STATUS = '6' OR STATUS = 'D' THEN --
             RETURN 'OK';
          ELSE
             RETURN 'NO6301';
          END IF;
       END IF;

    ELSIF REQCD = '69' THEN   --SR완료
       SELECT COUNT(*)
         INTO VCNT
         FROM CMC0100
        WHERE CC_SRID=ISRID
          AND CC_CREATEUSER=USERID
          AND CC_STATUS IN ('3','8','9');
       IF VCNT > 0 THEN
          RETCD := 'NO02342340';
       ELSE
          IF QRYGBN = '01' THEN
             SELECT COUNT(*)
               INTO VCNT
               FROM CMC0110
              WHERE CC_SRID=ISRID
                AND CC_STATUS='9';
             IF VCNT > 0 THEN
                SELECT COUNT(*)
                  INTO VCNT
                  FROM CMC0110
                 WHERE CC_SRID=ISRID
                   AND CC_STATUS NOT IN ('3','8','9');
                IF VCNT = 0 THEN
                   RETCD := 'OK';
                ELSE
                   RETCD := 'NO02';
                END IF;
             ELSE
                RETCD := 'OK';
             END IF;
          ELSE
             SELECT COUNT(*)
               INTO VCNT
               FROM CMC0110
              WHERE CC_SRID=ISRID
                AND CC_STATUS='9';
             IF VCNT > 0 THEN
                RETCD := 'NO02';
             ELSE
                SELECT COUNT(*)
                  INTO VCNT
                  FROM CMR0020
                 WHERE CR_ISRID=ISRID
                   AND CR_STATUS NOT IN ('0','9');
                IF VCNT = 0 THEN
                   RETCD := 'OK';
                END IF;
